void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
template<class F>void rejects(F f){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}check(rejected,"invalid indoor owner accepted");}
LeImage source(){auto result=LeImage::from_bytes(layout::GermanDataSegmentBegin,Bytes(0x21000));const auto compact=bmh::test::world12::country_rules(false);for(uint32_t i=0;i<compact.size();++i){const auto value=compact.u8(compact.base()+i);result.patch(compact.base()+i,&value,1);}const auto profile=DataProfile::international_11();for(size_t i=0;i<9;++i)result.patch(layout::LeagueSizes+uint32_t(i),&profile.leagues[i],1);return result;}
GameState reference(const LeImage& source){Bytes forms(0x160);const uint8_t outdoor_x[]={0,5,5,5,5,10,10,10,10,17,17},outdoor_y[]={4,1,3,5,7,1,3,5,7,3,5};const uint8_t indoor_x[]={0,5,5,5,5,11,11,11,11,17,18},indoor_y[]={4,2,3,6,7,2,3,6,7,4,4};for(size_t f=0;f<8;++f)for(size_t row=0;row<11;++row){forms[f*22+row]=outdoor_x[row];forms[f*22+11+row]=outdoor_y[row];forms[0xb0+f*22+row]=indoor_x[row];forms[0xb0+f*22+11+row]=indoor_y[row];}return startup_reference_state(source,DataProfile::international_11().counts,Bytes(0x360),forms);}
CareerSnapshot fixture(const GameState& reference,const LeImage& source,bool human){CareerSnapshot s;auto& w=s.world;w=bmh::test::world12::complete_world();w.catalogue.scope.international=false;w.players_initialized=true;w.markets.emplace();w.free_players.emplace();w.settings=CareerSettings{3,6,5,1,false};w.economy.emplace();w.economy->presentation_options.emplace();w.economy->presentation_options->fill(1);(*w.economy->presentation_options)[16*9+4]=0;uint32_t next=2000000;
    for(auto& [id,club]:w.clubs)for(size_t row=0;row<24;++row){if(club.roster[row].empty()){PlayerRecord p;p.id={next++};p.attributes.name="Fixture reserve";w.players[p.id]=p;club.roster[row]={p.id,uint16_t(row<17?2:0)};}auto& p=w.players.at(club.roster[row].player).attributes;p.w35c=60u|(80u<<7)|(85u<<14);p.w368=uint32_t(club.country)<<27;p.w364=uint32_t(row==0||row==11?0:row<5?1:row<9?2:3);}
    if(human){const auto club=w.membership[0].clubs[0];w.managers={{3,"Hall manager",club,{0},3}};WatcomRandom random(713);initialize_manager_contracts(w,3,reference,{3,false,false,false,6},random);w.managers[0].career.emplace();w.managers[0].career->season_records.emplace();w.managers[0].career->cup_titles.emplace();w.economy->managers[3].monthly.emplace();w.economy->managers[3].depreciation=0;}
    InitialCompetitionFields fields;auto club=w.clubs.begin();const size_t counts[]={64,24,32};for(size_t k=0;k<3;++k){for(size_t i=0;i<counts[k];++i)fields.fields[k].push_back((club++)->first);fields.holders[k]=fields.fields[k][0];}fields.champions={{Country::germany,w.membership[0].clubs[0]},{Country::england,w.membership[5].clubs[0]}};fields.domestic_holders={{Country::germany,w.membership[0].clubs[7]},{Country::england,w.membership[5].clubs[7]}};w.initial_competitions=fields;w.indoor=initial_indoor_season(w,source,reference);s.results=SeasonResults::empty(w.catalogue);s.game_seed=31;s.watcom_seed=713;s.validate();return s;}
AiLeagueConditions conditions(uint32_t date,bool hall){AiLeagueConditions c;c.date=date;c.month=month_code(date);c.temperature=15;c.rain=0;c.referee_properties.assign(50,0x24);c.presentation_buttons.assign(180,1);c.spectators=hall?10000:20000;return c;}
void winter_ranking(CareerSnapshot& state,const GameState& reference){GameRandom game(state.game_seed);WatcomRandom random(state.watcom_seed);HumanRoundHooks hooks;hooks.decline_unpresented_events=true;for(int round=1;round<=17;++round){state.date=uint32_t(round*7);for(uint32_t league:{0u,1u}){const bool human=std::any_of(state.world.managers.begin(),state.world.managers.end(),[&](const auto& manager){return state.world.clubs.at(manager.club).league==LeagueId{league};});const auto matches=league_fixtures(state.world,{league},round);std::vector<AiLeagueConditions> input(matches.size(),conditions(state.date,false));const auto scored=human?simulate_and_settle_human_league_round(state,reference,{league},round,input,{3,6,false,true},game,random,hooks):simulate_and_settle_ai_league_round(state.world,reference,{league},round,input,game,random);for(size_t m=0;m<scored.matches.size();++m)state.results.result(state.world.catalogue,{league},round,int(m))=scored.matches[m].score;state.league_rounds[league]=uint8_t(round);}}state.date=137;state.game_seed=game.seed();state.watcom_seed=random.seed();state.validate();}
struct SourceOracle {
    GameState game;std::vector<ClubId> clubs;
    SourceOracle(const CareerSnapshot& state,const GameState& reference){
        for(uint8_t local=0;local<5;++local){const auto& members=state.world.membership[local].clubs;clubs.insert(clubs.end(),members.begin(),members.end());}for(uint32_t league:{10u,5u,11u,12u}){const auto& members=state.world.membership[league].clubs;clubs.insert(clubs.end(),members.begin(),members.end());}
        std::vector<ClubId> humans;for(const auto& manager:state.world.managers)humans.push_back(manager.club);auto projection=humans.empty()?AiMatchProjection::create(state.world,{clubs[0]},reference):AiMatchProjection::create_for_humans(state,humans,reference,{3,6,false,true});install_career_economy(projection,state.world);game=projection.state;game.projected_match_clubs.clear();game.club_names={0};for(size_t i=0;i<clubs.size();++i){game.club_ids[i]=uint16_t(game.club_names.size());const auto& text=state.world.clubs.at(clubs[i]).name;game.club_names.insert(game.club_names.end(),text.begin(),text.end());game.club_names.push_back(0);}for(size_t m=0;m<humans.size();++m)game.manager_teams[m]=int(std::find(clubs.begin(),clubs.end(),humans[m])-clubs.begin());
        game.position_history.assign(size_t(runtime_dimensions.record_teams)*26,0);game.league_rounds.assign(9,0);for(uint32_t league:{0u,1u}){const auto round=state.league_rounds[league];game.league_rounds[league]=round;for(const auto& row:compute_standings(state.world,state.results,{league},round,{})){const auto team=size_t(std::find(clubs.begin(),clubs.end(),row.club)-clubs.begin());const auto offset=(team*13+(round-1)/3)*2;const auto word=uint16_t((row.rank-1)<<(((round-1)%3)*5));game.position_history[offset]=uint8_t(word);game.position_history[offset+1]=uint8_t(word>>8);}}
        auto& memory=game.memory;memory.set8(layout::Cup_AdvanceCup_RuntimeField4,0);memory.set8(layout::Cup_AdvanceCup_RuntimeField,1);for(size_t i=0;i<3;++i)memory.set16(layout::Cup_AdvanceCup_RuntimeField6+uint32_t(i*2),uint16_t(std::find(clubs.begin(),clubs.end(),state.world.indoor->previous_holders[i])-clubs.begin()));memory.add_block(layout::Cup_MastersQualification_RuntimeField,8);for(size_t i=0;i<4;++i)memory.set16(layout::Cup_MastersQualification_RuntimeField+uint32_t(i*2),state.world.indoor->initial_scratch_slots[i]);for(uint32_t i=0;i<8;++i)memory.set8(layout::ActiveSelectors+i,i?0x14:11);
    }
    void compare(const CareerSnapshot& state)const{const auto& indoor=*state.world.indoor;const auto& tournament=indoor.tournaments.back();for(size_t i=0;i<16;++i)check(tournament.teams[i]==clubs.at(game.memory.u16(layout::Teams+uint32_t(i*2)))&&tournament.scores[i]==game.memory.u16(layout::MatchdayGroupWorkspace+uint32_t(i*2)),"typed Hall field/results differ from Original Source workspace");for(size_t i=0;i<5;++i)check(tournament.played[i]==game.memory.u8(cup_entry_address(int(25+i))+0x1d),"typed Hall cursor differs from Source");for(size_t i=0;i<40;++i)check(indoor.points[i]==game.memory.u16(layout::Cup_AdvanceCup_ExecutableField+uint32_t(i*2))&&indoor.invitations[i]==game.memory.u16(layout::MatchdaySetup_IndoorTournamentDraw_RuntimeField+uint32_t(i*2)),"typed Masters points/invitations differ from Source");check(tournament.strength==game.memory.u8(layout::Cup_AdvanceCup_RuntimeField3),"typed Hall strength differs from Source");}
    void results(const IndoorResults& input,const IndoorSeason& model){for(const auto& group:input.groups){const auto& rule=model.rules[group.source_entry-25];for(size_t m=0;m<group.scores.size();++m)game.memory.set16(layout::MatchdayGroupWorkspace+uint32_t((rule.result_offset+group.played*(rule.teams/2)+m)*2),group.scores[m]);}}
};
CareerSnapshot* interrupted_draw=nullptr;
void change_draw_owner(int){draw_hook=nullptr;interrupted_draw->game_seed^=1;}
void programme(bool human){const auto rules=source();const auto ref=reference(rules);auto state=fixture(ref,rules,human);winter_ranking(state,ref);const auto before=state;SourceOracle oracle(state,ref);
    auto interrupted=state;interrupted_draw=&interrupted;draw_hook=change_draw_owner;rejects([&]{prepare_indoor_draw(interrupted,ref,rules);});draw_hook=nullptr;interrupted_draw=nullptr;auto changed=before;changed.game_seed^=1;check(interrupted==changed,"Source invitation draw overwrote an external career/seed change");
    const auto first_draw=prepare_indoor_draw(state,ref,rules);GameRandom source_game(before.game_seed);WatcomRandom source_random(before.watcom_seed);indoor_tournament_draw(oracle.game,source_game,source_random);oracle.compare(state);check(state.game_seed==source_game.seed()&&state.watcom_seed==source_random.seed(),"typed first field RNG differs from Source");check(first_draw.changed&&first_draw.game_draws==8,"first Source draw did not retain eight position shuffles");check(state.world.indoor->tournaments.size()==1&&state.world.indoor->selection_slots.size()==164,"first Source field lost its namespace");const auto drawn=state;check(!prepare_indoor_draw(state,ref,rules).changed&&state==drawn,"first field redrawn");const auto bytes=encode_world(state.world);auto old_json=cli::parse_json(std::string(bytes.begin(),bytes.end()));old_json.object()->at("version")=36;auto old_text=cli::dump_json(old_json);rejects([&]{decode_world(Bytes(old_text.begin(),old_text.end()));});old_json.object()->at("indoor")=nullptr;old_text=cli::dump_json(old_json);check(!decode_world(Bytes(old_text.begin(),old_text.end())).indoor,"older world invented indoor ownership");auto corrupt=state;++corrupt.world.indoor->points[0];rejects([&]{make_save(corrupt);});for(size_t slot=90;slot<164;++slot){const auto& club=state.world.clubs.at(state.world.indoor->selection_slots[slot]);check(club.league.value==10||club.league.value==5||club.league.value==11||club.league.value==12,"English lower division entered Original guest namespace");}size_t matches=0,passes=0;uint64_t field_game_draws=first_draw.game_draws;HumanRoundHooks hooks;hooks.decline_unpresented_events=true;hooks.before_matchday=[&](auto& projection,auto& engine){check(engine.indoor&&projection.state.indoor,"Hall pass used an outdoor engine state");for(uint8_t manager=0;manager<projection.human_managers();++manager){size_t pairs=0,unpaired=0;for(size_t row=0;row<11;++row){const auto partner=projection.state.tactics[size_t(manager)*0x840+row*0x58+0x3f];if(partner==255)++unpaired;else if(partner>row)++pairs;}check(pairs==5&&unpaired==1,"Source indoor formation lost five field pairs plus keeper");}};
    while(!state.world.indoor->masters_winner.valid()){
        const auto groups=prepare_indoor_groups(*state.world.indoor);std::vector<std::vector<AiLeagueConditions>> input;for(const auto& group:groups)input.emplace_back(group.matches.size(),conditions(state.date,true));auto repeated=state;GameRandom game(state.game_seed),again_game(state.game_seed);WatcomRandom random(state.watcom_seed),again_random(state.watcom_seed);
        const auto outcome=simulate_and_settle_indoor_pass(state,ref,groups,input,{3,6,false,true},game,random,hooks);const auto again=simulate_and_settle_indoor_pass(repeated,ref,groups,input,{3,6,false,true},again_game,again_random,hooks);check(repeated==state&&game.seed()==again_game.seed()&&random.seed()==again_random.seed(),"Hall scoring changed on identical replay");
        IndoorResults result{groups.front().revision,groups.front().tournament,{}};for(size_t i=0;i<groups.size();++i){result.groups.push_back({groups[i].source_entry,groups[i].played,outcome.groups[i].scores});matches+=outcome.groups[i].scores.size();for(auto minute:outcome.groups[i].end_minutes)check(minute==40||minute==0,"Hall match used an outdoor clock");}
        const auto scored=state;oracle.results(result,*state.world.indoor);source_game=GameRandom(state.game_seed);source_random=WatcomRandom(state.watcom_seed);MinuteReport source_report;advance_cup(oracle.game,11,source_random,source_report,&source_game);check(!source_report.unsupported,"Source oracle could not advance Hall stage");auto broken=result;broken.groups.back().scores.pop_back();rejects([&]{commit_indoor_results(state,broken,ref,rules);});check(state==scored,"bad later Hall group leaked an earlier result/draw");const auto transition=commit_indoor_results(state,result,ref,rules);field_game_draws+=transition.game_draws;oracle.compare(state);check(state.game_seed==source_game.seed()&&state.watcom_seed==source_random.seed(),"typed Hall transition RNG differs from Source");++passes;const auto saved=state;state=read_save(make_save(state));check(state==saved,"Hall state/results/points/seed lost at checkpoint");rejects([&]{commit_indoor_results(state,result,ref,rules);});
    }
    check(matches==96&&passes==30&&state.world.indoor->tournaments.size()==6&&state.world.indoor->tournaments.back().complete,"Source Hall programme lost a tournament/pass/match");check(field_game_draws==48,"Source field draws did not consume six eight-position game shuffles");check(state.world.indoor->tournaments[5].strength==state.world.indoor->tournaments[4].strength,"Masters recomputed the Source retained strength class");std::set<ClubId> hosts;for(auto host:state.world.indoor->hosts)check(host.valid()&&hosts.insert(host).second,"Source repeated an invitation tournament host");for(size_t slot=36;slot<40;++slot)check(state.world.indoor->points[slot]==0,"Source Masters points escaped the first two German leagues");for(const auto& t:state.world.indoor->tournaments)check(t.complete&&t.places[0].valid(),"Source Hall classification missing");std::cout<<"Original Hall programme human="<<human<<":96 actual Core matches,30 passes,5 invitations+Masters, every pass saved\n";
}
void date_passes(){const auto rules=source();const auto ref=reference(rules);auto state=fixture(ref,rules,true);winter_ranking(state,ref);prepare_indoor_draw(state,ref,rules);SeasonCalendar schedule;
    for(const auto& league:state.world.catalogue.leagues)for(uint8_t round=1;round<=league.rounds();++round){uint16_t day;if(league.id.value<=1)day=round<=17?uint16_t(round*7):uint16_t(200+(round-18)*7);else if(league.country==Country::england)day=round==1?157:uint16_t(180+(round-2)*4);else day=uint16_t(220+(round-1)*4);schedule.leagues.push_back({day,league.id,round});}
    schedule.others={{157,CalendarDomain::germany,0x4002},{158,CalendarDomain::germany,0x4002}};schedule.validate(state.world.catalogue);state.calendar=CalendarCursor{schedule,157,71};state.date=157;state.desktop.emplace();ManagerDesktop desk;desk.seat=3;state.desktop->managers={desk};state.desktop->manager_order={3};state.desktop->matchday_number=77;const auto epoch=calendar_epoch();state.progress=CareerProgress{ProgressPhase::scheduled_event,DayEntry::plain_day,156,0,uint16_t(epoch.year),uint8_t(epoch.weekday),3};state.validate();application::ManagerActionOwner owner{717,1};HumanRoundHooks hooks;hooks.decline_unpresented_events=true;
    const auto ordinary=*prepare_day(state);check(ordinary.indoor_date&&ordinary.indoor_ordinary_phase&&ordinary.indoor.empty()&&ordinary.leagues.size()==5,"coincident English leagues did not retain their separate ordinary pass");std::vector<application::AiDayLeagueConditions> leagues;for(const auto& plan:ordinary.leagues)leagues.push_back({plan.appointment,std::vector<AiLeagueConditions>(plan.matches.size(),conditions(state.date,false))});application::play_competition_day(state,owner,owner,ordinary,ref,{rules,rules},leagues,{},{},{3,6,false,true},hooks);check(state.date==157&&state.calendar->next_day==157&&state.world.indoor->date_pass&&state.world.indoor->date_pass->ordinary_completed,"ordinary pass advanced or lost its pending Hall date");const auto saved=state;check(read_save(make_save(state))==saved,"partial current-date English results did not roundtrip");auto lost_receipt=state;lost_receipt.world.indoor->date_pass->ordinary_completed=false;rejects([&]{make_save(lost_receipt);});
    const auto weather=application::prepare_event_weather(state,owner,owner,std::vector<uint8_t>(50,0x24),{rules,rules},&ref);check(weather.matches.size()==4&&state.prepared_event->groups.size()==2,"Hall weather repeated ordinary fixtures");const auto pending=make_save(state);check(pending.stream[7]=='I'&&read_save(pending)==state,"SI indoor pass identity/weather did not roundtrip");state.prepared_event.reset();
    for(int pass=0;pass<3;++pass){const auto ticket=*prepare_day(state);check(ticket.leagues.empty()&&ticket.cups.empty()&&ticket.indoor.size()==2&&!ticket.indoor_ordinary_phase,"ordinary fixtures repeated during Hall passes");std::vector<application::IndoorDayConditions> input;for(const auto& group:ticket.indoor)input.push_back({group,std::vector<AiLeagueConditions>(group.matches.size(),conditions(state.date,true))});application::play_competition_day(state,owner,owner,ticket,ref,{rules,rules},{},{},{},{3,6,false,true},hooks,input);check(state.date==uint32_t(pass<2?157:158),"Hall group pass changed the calendar at the wrong boundary");check(read_save(make_save(state))==state,"saved Hall pass owner lost current-date results");}
    check(!state.world.indoor->date_pass&&state.progress->phase==ProgressPhase::daily_services&&state.world.indoor->tournaments[0].played[0]==3,"first Hall date did not close once after three group passes");for(uint32_t league=5;league<=9;++league)check(state.league_rounds[league]==1,"English current-day round was replayed or lost");
    auto off=saved;off.world.indoor->date_pass.reset();off.calendar->next_day=158;off.date=158;off.progress.reset();(*off.world.economy->presentation_options)[16*9+4]=1;const auto quiet=prepare_day(off);check(quiet&&quiet->indoor.empty()&&quiet->others.empty(),"Q5 failed to suppress only German Hall fixtures");
}

