int main()try{install_runtime_profile(DataProfile::international_11());auto tables=bmh::test::authored_fixture_tables();tables[4]={"abcd","acdb","adbc"};set_fixture_tables(tables);programme(false);programme(true);date_passes();return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}
